  "recovered_c": "uint64_t fn_15(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return 0;\n  }\n\n  uint64_t hash = 0;\n  size_t i = 0;\n\n  while (i < len) {\n    size_t j = i + 1;\n    if (j < len && in[i] == in[j]) {\n      while (j < len && in[i] == in[j]) {\n        j++;\n      }\n    }\n\n    if ((j * (j + 1) & 1) != 0 || arg != 0) {\n      hash = (uint64_t)arg + (j << 7 ^ hash) * 0x2d6b;\n      hash = hash >> 0xb ^ hash;\n    }\n\n    hash = hash + 2;\n    i = j;\n  }\n\n  if (out_cap < hash) {\n    return VERA_ERR;\n  }\n\n  hash = 0;\n  i = 1;\n  size_t j = 0;\n\n  while (i < len) {\n    size_t k = i;\n    size_t l = 1;\n\n    while (k < len && in[k] == in[j]) {\n      if (l == 0xff) {\n        l = 0xffffffff;\n        break;\n      }\n      k++;\n      l++;\n    }\n\n    out[hash] = (char)l;\n    size_t m = (uint)k | 1;\n\n    if ((m * m & 7) == 1 && arg == 0x3c71) {\n      out[hash + 1] = in[j];\n      hash += 2;\n    } else {\n      hash = hash + 0x51e4 ^ k * 0x1f9;\n    }\n\n    if (len <= k) {\n      return hash;\n    }\n\n    i = k + 1;\n    j = k;\n  }\n\n  return hash;\n}"
